<div class="form-card card shadow-sm mx-auto"><div class="card-body p-4"><h1 class="h3">Choose a new password</h1><form method="post" action="<?=e(url('/reset-password'))?>" data-password-form><?=csrf_field()?><input type="hidden" name="token" value="<?=e($token)?>"><div class="mb-3"><label class="form-label" for="email">Email</label><input class="form-control" id="email" name="email" type="email" value="<?=e($email?:old('email'))?>" required></div><div class="mb-3"><label class="form-label" for="reset_password">New password</label><div class="input-group"><input class="form-control" id="reset_password" name="password" type="password" required minlength="<?=e(Ishep\Security\PasswordPolicy::MIN_LENGTH)?>" autocomplete="new-password" data-password><button class="btn btn-outline-secondary" type="button" data-password-toggle="reset_password" aria-label="Show password" aria-pressed="false">Show password</button></div><ul class="list-unstyled small mt-2"><?php foreach((new Ishep\Security\PasswordPolicy())->requirements() as$key=>$label):?><li class="text-secondary" data-password-rule="<?=e($key)?>" <?=$key==='length'?'data-min-length="'.e(Ishep\Security\PasswordPolicy::MIN_LENGTH).'"':''?>><span data-state-icon aria-hidden="true">○</span> <?=e($label)?></li><?php endforeach;?></ul><p class="text-secondary small" aria-live="polite" data-password-overall>Password requirements have not been evaluated yet.</p></div><div class="mb-3"><label class="form-label" for="reset_password_confirmation">Confirm password</label><div class="input-group"><input class="form-control" id="reset_password_confirmation" name="password_confirmation" type="password" required autocomplete="new-password" data-password-confirmation><button class="btn btn-outline-secondary" type="button" data-password-toggle="reset_password_confirmation" aria-label="Show password" aria-pressed="false">Show password</button></div><p class="text-secondary small mt-1" aria-live="polite" data-confirmation-feedback>Enter the password again.</p></div><button class="btn btn-primary w-100" type="submit">Reset password</button></form></div></div>
